UPDATE attempt a SET score = v.score, points = v.points, feedback = v.feedback, dimensions_json = v.dimensions_json, evaluated_at = v.evaluated_at FROM (VALUES
(CAST(#{it.id} AS bigint), CAST(#{it.score} AS double precision), CAST(#{it.points} AS double precision), #{it.feedback}, #{it.dimensionsJson}, CAST(#{it.evaluatedAt} AS bigint))
) AS v(id, score, points, feedback, dimensions_json, evaluated_at) WHERE a.id = v.id AND a.user_id = #{userId}
